import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useAsOf } from '../asof/asof.slot';
import { usePreview } from '../preview/preview';

// Who is signed in and which sheet is active live in the URL (`user`, `sheet`), so any feature
// reads them directly. There is no password: signing in is typing a name.
export const useUser = () => useSearchParam('user', asString);
export const useSheetId = () => useSearchParam('sheet', asString);

/** `today` (yyyy-MM-dd) is the sheet's own date: every date decision and default date on the
 *  sheet uses it, never the browser's clock. An `archived` sheet stays visible and refuses every change. `parent` is the
 *  id of its parent sheet (whose rates apply where it has none), null when none. */
export type Sheet = { id: string; today: string; archived: boolean; parent: string | null };

/** The active sheet as the store holds it. Keyed ['sheet', id]: every per-sheet key starts so. */
export function useSheet(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(['sheet', sheetId], now),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`, now),
    enabled: sheetId !== '',
  });
}

/** The sheet's today (yyyy-MM-dd), or '' while the sheet loads, as every figure on this screen takes it: the preview
 *  date while this screen previews one (see features/preview; not while it shows the sheet as of a date, nor in a read
 *  of the sheet as it is now). Use it for every figure; a change and its defaults use the sheet's real today. */
export function useSheetToday(sheetId: string): string {
  const today = useSheet(sheetId).data?.today ?? '';
  const [preview] = usePreview();
  const [asOf] = useAsOf();
  const now = useReadNow();
  return today !== '' && preview !== '' && asOf === '' && !now ? preview : today;
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date this screen shows the sheet as of (yyyy-MM-dd; the `asof` search param, see features/asof), or ''. While
 *  set, every read of a sheet asks for it as it stood then (`asOf`), and every change carries it (the X-As-Of header)
 *  so the server refuses it. */
export function viewAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return /^"?(\d{4}-\d{2}-\d{2})"?$/.exec(raw)?.[1] ?? '';
}

/** The date this screen previews the sheet's today as (yyyy-MM-dd; the `preview` search param, see features/preview),
 *  or ''. While set, and no as-of date is, every read of a sheet asks for its figures as if its today were that date
 *  (`preview`); a change never carries it, so every change uses the sheet's real today. */
export function viewPreview(): string {
  const raw = new URLSearchParams(window.location.search).get('preview') ?? '';
  return /^"?(\d{4}-\d{2}-\d{2})"?$/.exec(raw)?.[1] ?? '';
}

async function send<T>(path: string, init?: RequestInit, now = false): Promise<T> {
  const asOf = now ? '' : viewAsOf();
  const preview = now || asOf !== '' ? '' : viewPreview();
  if (preview !== '' && path.startsWith('/api/sheets/') && (init?.method ?? 'GET') === 'GET') {
    path = `${path}${path.includes('?') ? '&' : '?'}preview=${preview}`;
  }
  if (asOf !== '' && path.startsWith('/api/sheets/')) {
    if ((init?.method ?? 'GET') === 'GET') {
      path = `${path}${path.includes('?') ? '&' : '?'}asOf=${asOf}`;
    } else {
      init = { ...init, headers: { ...(init?.headers as Record<string, string>), 'X-As-Of': asOf } };
    }
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

/** A read; `now` asks for the sheet as it is now, whatever the as-of date (see query/readNow). */
export function getJson<T>(path: string, now = false): Promise<T> {
  return send<T>(path, undefined, now);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
